/** Płaska lista [x0, y0, …] → [[x, y], …]. */
export function tnLoop(flatList) {
  const out = [];
  for (let i = 0; i + 1 < flatList.length; i += 2) out.push([flatList[i], flatList[i + 1]]);
  return out;
}
